('logico', 'a5b96025-9249-4b91-8a03-e00eb537aacd', 'Silogismos', null, 'Todos os comissários são treinados em primeiros socorros. Maria é comissária. Logo:', null, '[{"letra": "A", "texto": "Nem todos os comissários são treinados", "imagem_url": null}, {"letra": "B", "texto": "Maria é treinada em primeiros socorros", "imagem_url": null}, {"letra": "C", "texto": "Maria pode não saber primeiros socorros", "imagem_url": null}, {"letra": "D", "texto": "Maria não é comissária", "imagem_url": null}]'::jsonb, 'B', 'Silogismo válido: Se todos os A são B, e C é A, então C é B'),
('logico', 'b8e1cf4a-d0f4-4b96-a7ee-ba9a5982fe7c', 'Silogismos', null, 'Nenhum passageiro pode acessar a cabine de comando. João é passageiro. Portanto:', null, '[{"letra": "A", "texto": "Alguns passageiros acessam a cabine", "imagem_url": null}, {"letra": "B", "texto": "João não pode acessar a cabine de comando", "imagem_url": null}, {"letra": "C", "texto": "João pode acessar a cabine", "imagem_url": null}, {"letra": "D", "texto": "João é tripulante", "imagem_url": null}]'::jsonb, 'B', 'Silogismo válido: Se nenhum A é B, e C é A, então C não é B'),
('logico', 'c12e0a1d-e11b-4d12-8581-d2041874c022', 'Silogismos', null, 'Todos os voos internacionais exigem passaporte. O voo para Paris é internacional. Logo:', null, '[{"letra": "A", "texto": "Passaportes são opcionais", "imagem_url": null}, {"letra": "B", "texto": "Alguns voos para Paris não exigem passaporte", "imagem_url": null}, {"letra": "C", "texto": "O voo para Paris exige passaporte", "imagem_url": null}, {"letra": "D", "texto": "O voo para Paris não exige passaporte", "imagem_url": null}]'::jsonb, 'C', 'Premissa maior + premissa menor = conclusão válida'),
('logico', '72441ec9-666e-4e5c-b863-ce5e50822937', 'Silogismos', null, 'Alguns pilotos falam três idiomas. Carlos é piloto. Pode-se concluir que:', null, '[{"letra": "A", "texto": "Carlos pode falar três idiomas", "imagem_url": null}, {"letra": "B", "texto": "Carlos certamente fala três idiomas", "imagem_url": null}, {"letra": "C", "texto": "Carlos não fala três idiomas", "imagem_url": null}, {"letra": "D", "texto": "Todos os pilotos falam três idiomas", "imagem_url": null}]'::jsonb, 'A', 'Com "alguns", só podemos concluir possibilidade, não certeza'),
('logico', '712f06e2-1ce5-4167-aabc-1ab3d79809a8', 'Silogismos', null, 'Todos os aeroportos têm torre de controle. Congonhas é um aeroporto. Portanto:', null, '[{"letra": "A", "texto": "Congonhas tem torre de controle", "imagem_url": null}, {"letra": "B", "texto": "Algumas torres ficam fora de aeroportos", "imagem_url": null}, {"letra": "C", "texto": "Congonhas não é aeroporto", "imagem_url": null}, {"letra": "D", "texto": "Congonhas pode não ter torre de controle", "imagem_url": null}]'::jsonb, 'A', 'Silogismo categórico válido'),
('logico', '85d23303-3ad6-41fe-9e5a-c12fb2b97abd', 'Silogismos', null, 'Nenhum objeto metálico pode passar no detector sem alarme. Chaves são objetos metálicos. Logo:', null, '[{"letra": "A", "texto": "Chaves disparam o alarme ao passar", "imagem_url": null}, {"letra": "B", "texto": "Chaves não são metálicas", "imagem_url": null}, {"letra": "C", "texto": "Alguns metais não disparam alarme", "imagem_url": null}, {"letra": "D", "texto": "Chaves passam sem alarme", "imagem_url": null}]'::jsonb, 'A', 'Negação universal aplicada a caso particular'),
('logico', '6c3406d2-d69b-4c8b-9300-939b946f7653', 'Silogismos', null, 'Todos os comissários usam uniforme. Pessoas de uniforme seguem código de vestimenta. Logo:', null, '[{"letra": "A", "texto": "Alguns comissários não seguem código", "imagem_url": null}, {"letra": "B", "texto": "Código não se aplica a comissários", "imagem_url": null}, {"letra": "C", "texto": "Comissários seguem código de vestimenta", "imagem_url": null}, {"letra": "D", "texto": "Uniformes são opcionais", "imagem_url": null}]'::jsonb, 'C', 'Silogismo em cadeia (transitivo)'),
('logico', 'ec89f8c9-db55-441a-8abd-12a0d08be1be', 'Silogismos', null, 'Se chove, o voo atrasa. Está chovendo. Portanto:', null, '[{"letra": "A", "texto": "A chuva não afeta voos", "imagem_url": null}, {"letra": "B", "texto": "O voo pode não atrasar", "imagem_url": null}, {"letra": "C", "texto": "O voo decola no horário", "imagem_url": null}, {"letra": "D", "texto": "O voo atrasará", "imagem_url": null}]'::jsonb, 'D', 'Modus ponens: Se P então Q, P é verdade, logo Q'),
('logico', '689f899b-943e-4845-96e2-c7c47fdae8aa', 'Silogismos', null, 'Se o passageiro não apresentar documento, não embarca. Ana não apresentou documento. Logo:', null, '[{"letra": "A", "texto": "Documentos são desnecessários", "imagem_url": null}, {"letra": "B", "texto": "Ana pode embarcar", "imagem_url": null}, {"letra": "C", "texto": "Ana não embarcará", "imagem_url": null}, {"letra": "D", "texto": "Ana embarcará", "imagem_url": null}]'::jsonb, 'C', 'Modus ponens com negação'),
('logico', '928e04db-02e6-4c75-8247-100b05c028bc', 'Silogismos', null, 'Todos os aviões têm saídas de emergência. Boeing 737 é um avião. Portanto:', null, '[{"letra": "A", "texto": "Saídas são opcionais", "imagem_url": null}, {"letra": "B", "texto": "Boeing 737 tem saídas de emergência", "imagem_url": null}, {"letra": "C", "texto": "Nem todos os aviões têm saídas", "imagem_url": null}, {"letra": "D", "texto": "Boeing 737 pode não ter saídas", "imagem_url": null}]'::jsonb, 'B', 'Silogismo categórico válido'),
('logico', '3c92ff3b-ce76-48a0-b846-acbf191e0235', 'Silogismos', null, 'Nenhum menor desacompanhado pode viajar sem autorização. Pedro tem 15 anos e está sozinho. Logo:', null, '[{"letra": "A", "texto": "Pedro pode viajar sem autorização", "imagem_url": null}, {"letra": "B", "texto": "Menores não precisam de autorização", "imagem_url": null}, {"letra": "C", "texto": "Pedro é maior de idade", "imagem_url": null}, {"letra": "D", "texto": "Pedro precisa de autorização para viajar", "imagem_url": null}]'::jsonb, 'D', 'Aplicação de regra negativa universal'),
('logico', 'adb90c26-7ba6-4d9a-ac8d-9718d3e05d40', 'Silogismos', null, 'Se não houver combustível suficiente, o avião não decola. Há combustível suficiente. Pode-se concluir que:', null, '[{"letra": "A", "texto": "O avião certamente decola", "imagem_url": null}, {"letra": "B", "texto": "Não se pode concluir se o avião decola", "imagem_url": null}, {"letra": "C", "texto": "O avião não decola", "imagem_url": null}, {"letra": "D", "texto": "Combustível é irrelevante", "imagem_url": null}]'::jsonb, 'B', 'Negar o antecedente não garante o consequente'),
('logico', 'e1d293a4-e9f2-472b-b003-61b87397b38d', 'Silogismos', null, 'Todos os voos noturnos têm serviço de bordo reduzido. O voo das 23h é noturno. Logo:', null, '[{"letra": "A", "texto": "Voos noturnos têm mais serviço", "imagem_url": null}, {"letra": "B", "texto": "O voo das 23h tem serviço completo", "imagem_url": null}, {"letra": "C", "texto": "O voo das 23h tem serviço reduzido", "imagem_url": null}, {"letra": "D", "texto": "O voo é diurno", "imagem_url": null}]'::jsonb, 'C', 'Silogismo válido'),
('logico', '910589d8-5ff7-48f9-8424-59426e67456b', 'Silogismos', null, 'Nenhum líquido acima de 100ml pode ser levado na cabine. Água 500ml é um líquido. Portanto:', null, '[{"letra": "A", "texto": "Pode ser levada na cabine", "imagem_url": null}, {"letra": "B", "texto": "Não pode ser levada na cabine", "imagem_url": null}, {"letra": "C", "texto": "Depende do tipo de líquido", "imagem_url": null}, {"letra": "D", "texto": "Pode ser levada na mala", "imagem_url": null}]'::jsonb, 'B', 'Aplicação de regra restritiva'),
('logico', '872548fc-2ab8-4402-a64f-cc044801fdaf', 'Silogismos', null, 'Se a turbulência é severa, os cintos devem ser afivelados. A turbulência é severa. Logo:', null, '[{"letra": "A", "texto": "Cintos podem ficar soltos", "imagem_url": null}, {"letra": "B", "texto": "Cintos devem ser afivelados", "imagem_url": null}, {"letra": "C", "texto": "Turbulência leve dispensa cintos", "imagem_url": null}, {"letra": "D", "texto": "Não há relação com cintos", "imagem_url": null}]'::jsonb, 'B', 'Modus ponens direto'),
('logico', '6cc846ab-f0f7-4508-84d7-7d1ec613ed77', 'Silogismos', null, 'Se o voo está cheio, não há upgrade disponível. Há upgrade disponível. Pode-se concluir que:', null, '[{"letra": "A", "texto": "O voo está cheio", "imagem_url": null}, {"letra": "B", "texto": "Upgrades independem de lotação", "imagem_url": null}, {"letra": "C", "texto": "O voo não está cheio", "imagem_url": null}, {"letra": "D", "texto": "O voo pode estar cheio", "imagem_url": null}]'::jsonb, 'C', 'Modus tollens: Se P então Q, não Q, logo não P'),
('logico', 'a6ee08fc-f10a-4977-9b53-e0aff9a09877', 'Silogismos', null, 'Se a bagagem excede o peso, paga-se taxa extra. A bagagem não excede o peso. Logo:', null, '[{"letra": "A", "texto": "Paga-se taxa extra", "imagem_url": null}, {"letra": "B", "texto": "Não se pode concluir sobre taxa", "imagem_url": null}, {"letra": "C", "texto": "Certamente não há taxa", "imagem_url": null}, {"letra": "D", "texto": "O peso é irrelevante", "imagem_url": null}]'::jsonb, 'B', 'Negar antecedente não garante consequente'),
('logico', '027f9eab-f860-4085-8d53-f046a1dd830e', 'Silogismos', null, 'Se o passageiro é VIP, tem acesso ao lounge. Roberto não tem acesso ao lounge. Portanto:', null, '[{"letra": "A", "texto": "Lounge é aberto a todos", "imagem_url": null}, {"letra": "B", "texto": "Roberto é VIP", "imagem_url": null}, {"letra": "C", "texto": "Roberto não é VIP", "imagem_url": null}, {"letra": "D", "texto": "Roberto pode ser VIP", "imagem_url": null}]'::jsonb, 'C', 'Modus tollens válido'),
('logico', 'f94fa0b8-4423-4c5c-924d-2c8a4dc18ba9', 'Silogismos', null, 'Se houver neblina, o aeroporto fecha. O aeroporto está aberto. Logo:', null, '[{"letra": "A", "texto": "Há neblina", "imagem_url": null}, {"letra": "B", "texto": "Não há neblina", "imagem_url": null}, {"letra": "C", "texto": "Pode haver neblina", "imagem_url": null}, {"letra": "D", "texto": "Neblina é irrelevante", "imagem_url": null}]'::jsonb, 'B', 'Modus tollens: consequente falso implica antecedente falso'),
('logico', '01bc4924-fcce-4abf-9de4-a16f6fe4656a', 'Silogismos', null, 'Se a reserva é cancelada em 24h, há reembolso total. João cancelou em 24h. Portanto:', null, '[{"letra": "A", "texto": "Cancelamento não gera reembolso", "imagem_url": null}, {"letra": "B", "texto": "João não tem reembolso", "imagem_url": null}, {"letra": "C", "texto": "Reembolso é parcial", "imagem_url": null}, {"letra": "D", "texto": "João tem reembolso total", "imagem_url": null}]'::jsonb, 'D', 'Modus ponens direto'),
('logico', 'f5142ded-9fc2-4c53-9380-2e795a38babd', 'Silogismos', null, 'O voo parte às 10h ou às 14h. Não parte às 10h. Logo:', null, '[{"letra": "A", "texto": "Não há voo", "imagem_url": null}, {"letra": "B", "texto": "O voo parte às 14h", "imagem_url": null}, {"letra": "C", "texto": "Pode partir em outro horário", "imagem_url": null}, {"letra": "D", "texto": "Parte às 10h e às 14h", "imagem_url": null}]'::jsonb, 'B', 'Silogismo disjuntivo: A ou B, não A, logo B'),
('logico', '8b0fbaf8-3e34-4c8e-80e6-40d35e978d0d', 'Silogismos', null, 'A refeição é carne ou frango. O passageiro não quer carne. Portanto:', null, '[{"letra": "A", "texto": "Não há refeição", "imagem_url": null}, {"letra": "B", "texto": "O passageiro receberá frango", "imagem_url": null}, {"letra": "C", "texto": "Pode haver outra opção", "imagem_url": null}, {"letra": "D", "texto": "O passageiro quer carne", "imagem_url": null}]'::jsonb, 'B', 'Eliminação de alternativa'),
('logico', '5c4c5aea-59a4-45eb-bfc9-8365b478add7', 'Silogismos', null, 'O embarque é pelo portão A ou pelo portão B. Não é pelo portão A. Logo:', null, '[{"letra": "A", "texto": "Não há embarque", "imagem_url": null}, {"letra": "B", "texto": "O embarque é pelo portão B", "imagem_url": null}, {"letra": "C", "texto": "Pode ser pelo portão C", "imagem_url": null}, {"letra": "D", "texto": "É pelo portão A", "imagem_url": null}]'::jsonb, 'B', 'Silogismo disjuntivo válido'),
('logico', '830e90d0-4444-488a-be6b-3b83f092bf5a', 'Silogismos', null, 'A classe é econômica ou executiva. Ana não está na econômica. Portanto:', null, '[{"letra": "A", "texto": "Ana está na executiva", "imagem_url": null}, {"letra": "B", "texto": "Ana está na econômica", "imagem_url": null}, {"letra": "C", "texto": "Ana está na primeira classe", "imagem_url": null}, {"letra": "D", "texto": "Ana não viaja", "imagem_url": null}]'::jsonb, 'A', 'Disjunção exclusiva'),
('logico', '05943e19-7183-4aa8-a998-b02e7b058455', 'Silogismos', null, 'O pagamento é em dinheiro ou cartão. Não foi em cartão. Logo:', null, '[{"letra": "A", "texto": "Não houve pagamento", "imagem_url": null}, {"letra": "B", "texto": "O pagamento foi em dinheiro", "imagem_url": null}, {"letra": "C", "texto": "Pode ser outro método", "imagem_url": null}, {"letra": "D", "texto": "Foi em cartão", "imagem_url": null}]'::jsonb, 'B', 'Eliminação de alternativa'),
('logico', '8f487df1-e0c7-4fec-b179-ffd0a44ae3c3', 'Silogismos', null, 'Alguns pilotos são altos. Carlos é alto. Logo, Carlos é piloto. Esta conclusão é:', null, '[{"letra": "A", "texto": "Depende do contexto", "imagem_url": null}, {"letra": "B", "texto": "Parcialmente válida", "imagem_url": null}, {"letra": "C", "texto": "Válida", "imagem_url": null}, {"letra": "D", "texto": "Inválida - falácia de afirmação do consequente", "imagem_url": null}]'::jsonb, 'D', 'Falácia: ser alto não implica ser piloto'),
('logico', '6c204005-10bc-4842-ba74-821884230328', 'Silogismos', null, 'Todos os aviões voam. Pássaros voam. Logo, pássaros são aviões. Esta conclusão é:', null, '[{"letra": "A", "texto": "Inválida - falácia do termo médio não distribuído", "imagem_url": null}, {"letra": "B", "texto": "Válida", "imagem_url": null}, {"letra": "C", "texto": "Depende da definição", "imagem_url": null}, {"letra": "D", "texto": "Parcialmente válida", "imagem_url": null}]'::jsonb, 'A', 'Voar não é exclusivo de aviões'),
('logico', '3107c39d-3cce-49f1-9cad-6a01e28560fd', 'Silogismos', null, 'Se chove, a pista fica molhada. A pista está molhada. Logo, choveu. Esta conclusão é:', null, '[{"letra": "A", "texto": "Válida", "imagem_url": null}, {"letra": "B", "texto": "Sempre válida", "imagem_url": null}, {"letra": "C", "texto": "Parcialmente válida", "imagem_url": null}, {"letra": "D", "texto": "Inválida - afirmação do consequente", "imagem_url": null}]'::jsonb, 'D', 'A pista pode estar molhada por outros motivos'),
('logico', 'b1cd0e05-5fc9-4d55-a851-997da8822044', 'Silogismos', null, 'Nenhum gato é cachorro. Rex não é gato. Logo, Rex é cachorro. Esta conclusão é:', null, '[{"letra": "A", "texto": "Depende de Rex", "imagem_url": null}, {"letra": "B", "texto": "Inválida - não se pode concluir", "imagem_url": null}, {"letra": "C", "texto": "Válida", "imagem_url": null}, {"letra": "D", "texto": "Parcialmente válida", "imagem_url": null}]'::jsonb, 'B', 'Rex pode ser qualquer coisa, não necessariamente cachorro'),
('logico', '0912f384-7005-47ae-828d-4efc8b01d844', 'Silogismos', null, 'Todos os médicos estudam anatomia. João estuda anatomia. Logo, João é médico. É:', null, '[{"letra": "A", "texto": "Inválido - outros também estudam anatomia", "imagem_url": null}, {"letra": "B", "texto": "Parcialmente válido", "imagem_url": null}, {"letra": "C", "texto": "Válido", "imagem_url": null}, {"letra": "D", "texto": "Depende de João", "imagem_url": null}]'::jsonb, 'A', 'Estudar anatomia não é exclusivo de médicos'),
('logico', 'ecaacf1b-ff09-4792-bdc6-513ef20ba5e3', 'Silogismos', null, 'Em um aeroporto, se A implica B, e B implica C, então:', null, '[{"letra": "A", "texto": "A implica C", "imagem_url": null}, {"letra": "B", "texto": "C implica A", "imagem_url": null}, {"letra": "C", "texto": "Não há relação entre A e C", "imagem_url": null}, {"letra": "D", "texto": "A e C são independentes", "imagem_url": null}]'::jsonb, 'A', 'Transitividade lógica: Se A→B e B→C, então A→C'),
('logico', '502d95b7-323c-449a-9e60-4ffd7309c2d3', 'Silogismos', null, 'Se todos os A são B, e todos os B são C, então:', null, '[{"letra": "A", "texto": "Todos os A são C", "imagem_url": null}, {"letra": "B", "texto": "Alguns A são C", "imagem_url": null}, {"letra": "C", "texto": "Nenhum A é C", "imagem_url": null}, {"letra": "D", "texto": "Não se pode concluir", "imagem_url": null}]'::jsonb, 'A', 'Silogismo categórico transitivo'),
('logico', '6d35b18b-4012-4b19-a474-513803128748', 'Silogismos', null, 'Se nenhum A é B, e todos os C são A, então:', null, '[{"letra": "A", "texto": "Todos os C são B", "imagem_url": null}, {"letra": "B", "texto": "Nenhum C é B", "imagem_url": null}, {"letra": "C", "texto": "Alguns C são B", "imagem_url": null}, {"letra": "D", "texto": "Não há relação", "imagem_url": null}]'::jsonb, 'B', 'Se C⊂A e A∩B=∅, então C∩B=∅'),
('logico', '8fc92c42-be9c-4d97-b096-0d20bcf333fa', 'Silogismos', null, 'Se alguns A são B, e todos os B são C, então:', null, '[{"letra": "A", "texto": "Alguns A são C", "imagem_url": null}, {"letra": "B", "texto": "Nenhum A é C", "imagem_url": null}, {"letra": "C", "texto": "Todos os A são C", "imagem_url": null}, {"letra": "D", "texto": "Todos os C são A", "imagem_url": null}]'::jsonb, 'A', 'Alguns A são B, e esses B são C, logo alguns A são C'),
('logico', 'da4c7d99-eba4-437e-975c-a31a943c26aa', 'Silogismos', null, 'Se A ou B é verdadeiro, e A é falso, então:', null, '[{"letra": "A", "texto": "B é falso", "imagem_url": null}, {"letra": "B", "texto": "B é verdadeiro", "imagem_url": null}, {"letra": "C", "texto": "Ambos são falsos", "imagem_url": null}, {"letra": "D", "texto": "Não se pode determinar", "imagem_url": null}]'::jsonb, 'B', 'Disjunção: se uma parte é falsa, a outra deve ser verdadeira'),
('logico', '1f107e74-7692-4537-a543-e4272672d00e', 'Silogismos', null, 'Ana é mais alta que Bia. Bia é mais alta que Carla. Quem é a mais baixa?', null, '[{"letra": "A", "texto": "Ana", "imagem_url": null}, {"letra": "B", "texto": "Bia", "imagem_url": null}, {"letra": "C", "texto": "Carla", "imagem_url": null}, {"letra": "D", "texto": "Não é possível determinar", "imagem_url": null}]'::jsonb, 'C', 'Ana > Bia > Carla, logo Carla é a mais baixa'),
('logico', '0385c6fa-3cd3-4c49-8874-7446ab699b61', 'Silogismos', null, 'O voo de SP chega antes do voo do RJ. O voo de MG chega antes do de SP. Qual chega primeiro?', null, '[{"letra": "A", "texto": "Todos ao mesmo tempo", "imagem_url": null}, {"letra": "B", "texto": "RJ", "imagem_url": null}, {"letra": "C", "texto": "SP", "imagem_url": null}, {"letra": "D", "texto": "MG", "imagem_url": null}]'::jsonb, 'D', 'MG < SP < RJ, logo MG chega primeiro'),
('logico', '453b9dba-98b2-4bc2-bb88-4aaffeec2b3f', 'Silogismos', null, 'Pedro é mais velho que João. João é mais velho que Maria. Maria é mais velha que Pedro?', null, '[{"letra": "A", "texto": "Sim", "imagem_url": null}, {"letra": "B", "texto": "Não", "imagem_url": null}, {"letra": "C", "texto": "Talvez", "imagem_url": null}, {"letra": "D", "texto": "Depende", "imagem_url": null}]'::jsonb, 'B', 'Pedro > João > Maria, logo Maria não é mais velha que Pedro'),
('logico', 'ceecd895-98be-4280-a9a2-1d0eea8df63b', 'Silogismos', null, 'A sala A é maior que a B. A sala C é menor que a B. Qual é a menor?', null, '[{"letra": "A", "texto": "A", "imagem_url": null}, {"letra": "B", "texto": "B", "imagem_url": null}, {"letra": "C", "texto": "C", "imagem_url": null}, {"letra": "D", "texto": "Todas iguais", "imagem_url": null}]'::jsonb, 'C', 'A > B > C, logo C é a menor'),
('logico', 'c9af60fb-e633-412e-90d3-e4c19fbe796f', 'Silogismos', null, 'O avião X é mais rápido que Y. Y é mais rápido que Z. X é mais rápido que Z?', null, '[{"letra": "A", "texto": "Sim", "imagem_url": null}, {"letra": "B", "texto": "Não", "imagem_url": null}, {"letra": "C", "texto": "Talvez", "imagem_url": null}, {"letra": "D", "texto": "São iguais", "imagem_url": null}]'::jsonb, 'A', 'X > Y > Z, logo X > Z'),
('logico', 'b53ab533-b592-4a5f-beea-d9580968915a', 'Silogismos', null, 'Todos os tripulantes passam por treinamento. Ana é tripulante. Logo:', null, '[{"letra": "A", "texto": "Ana passou por treinamento", "imagem_url": null}, {"letra": "B", "texto": "Ana não é tripulante", "imagem_url": null}, {"letra": "C", "texto": "Treinamento é opcional", "imagem_url": null}, {"letra": "D", "texto": "Ana pode não ter treinamento", "imagem_url": null}]'::jsonb, 'A', 'Silogismo universal afirmativo'),
('logico', 'd3398ad4-b665-4c64-b02e-17d3823be259', 'Silogismos', null, 'Nenhum bagagem pode exceder 32kg. Esta mala pesa 35kg. Portanto:', null, '[{"letra": "A", "texto": "Pode ser despachada", "imagem_url": null}, {"letra": "B", "texto": "Não pode ser despachada", "imagem_url": null}, {"letra": "C", "texto": "Depende da companhia", "imagem_url": null}, {"letra": "D", "texto": "O peso é aceitável", "imagem_url": null}]'::jsonb, 'B', 'Aplicação de regra restritiva'),
('logico', '7ee4f4fa-6a28-42ed-8cf8-c2a1be52e689', 'Silogismos', null, 'Se o check-in online falha, deve-se ir ao balcão. O check-in online falhou. Logo:', null, '[{"letra": "A", "texto": "Não precisa ir ao balcão", "imagem_url": null}, {"letra": "B", "texto": "Deve-se ir ao balcão", "imagem_url": null}, {"letra": "C", "texto": "O check-in funcionou", "imagem_url": null}, {"letra": "D", "texto": "Balcão está fechado", "imagem_url": null}]'::jsonb, 'B', 'Modus ponens'),
('logico', '65140ffe-5de5-4bea-a93f-7b8a77b14b66', 'Silogismos', null, 'Todos os assentos premium têm mais espaço. O assento 2A é premium. Portanto:', null, '[{"letra": "A", "texto": "Premium não garante espaço", "imagem_url": null}, {"letra": "B", "texto": "2A tem mais espaço", "imagem_url": null}, {"letra": "C", "texto": "2A tem espaço normal", "imagem_url": null}, {"letra": "D", "texto": "2A não é premium", "imagem_url": null}]'::jsonb, 'B', 'Silogismo categórico'),
('logico', '6f700180-3672-4647-8984-885e5f79edce', 'Silogismos', null, 'Se a escala é longa, os passageiros recebem voucher. A escala é de 8 horas. Logo:', null, '[{"letra": "A", "texto": "Não há voucher", "imagem_url": null}, {"letra": "B", "texto": "Passageiros recebem voucher", "imagem_url": null}, {"letra": "C", "texto": "Escala curta", "imagem_url": null}, {"letra": "D", "texto": "Voucher é opcional", "imagem_url": null}]'::jsonb, 'B', '8 horas é escala longa, logo há voucher'),
('logico', 'ddb1bebd-8690-4e76-8afc-097a0766a77f', 'Silogismos', null, 'Nenhum voo doméstico exige visto. O voo para Salvador é doméstico. Portanto:', null, '[{"letra": "A", "texto": "Exige visto", "imagem_url": null}, {"letra": "B", "texto": "Não exige visto", "imagem_url": null}, {"letra": "C", "texto": "Visto é opcional", "imagem_url": null}, {"letra": "D", "texto": "Salvador é internacional", "imagem_url": null}]'::jsonb, 'B', 'Silogismo negativo universal'),
('logico', '805d27e3-40bb-4d45-9c4b-d051e4389002', 'Silogismos', null, 'Se o tempo fecha, o voo é cancelado. O voo não foi cancelado. Logo:', null, '[{"letra": "A", "texto": "O tempo pode ter fechado", "imagem_url": null}, {"letra": "B", "texto": "Cancelamento foi por outro motivo", "imagem_url": null}, {"letra": "C", "texto": "O tempo não fechou", "imagem_url": null}, {"letra": "D", "texto": "O tempo fechou", "imagem_url": null}]'::jsonb, 'C', 'Modus tollens'),
('logico', '8f764c13-bc41-4b8e-8502-3dac6d922a6e', 'Silogismos', null, 'Todos os pilotos têm licença. Quem tem licença passou em exames. Logo:', null, '[{"letra": "A", "texto": "Pilotos passaram em exames", "imagem_url": null}, {"letra": "B", "texto": "Pilotos não passaram em exames", "imagem_url": null}, {"letra": "C", "texto": "Licença dispensa exames", "imagem_url": null}, {"letra": "D", "texto": "Exames são opcionais", "imagem_url": null}]'::jsonb, 'A', 'Silogismo transitivo'),
('logico', 'a1f8752e-7ed4-4ed7-9440-605f6bfbd384', 'Silogismos', null, 'Algumas aeronaves são jatos. Todos os jatos são rápidos. Logo:', null, '[{"letra": "A", "texto": "Todas aeronaves são rápidas", "imagem_url": null}, {"letra": "B", "texto": "Algumas aeronaves são rápidas", "imagem_url": null}, {"letra": "C", "texto": "Nenhuma aeronave é rápida", "imagem_url": null}, {"letra": "D", "texto": "Jatos são lentos", "imagem_url": null}]'::jsonb, 'B', 'Conclusão particular de premissas mistas'),
('logico', 'a5d8fbf3-f708-4a0a-956d-4cbd7b7fdc44', 'Silogismos', null, 'Se é feriado, os voos estão cheios. Os voos não estão cheios. Portanto:', null, '[{"letra": "A", "texto": "É feriado", "imagem_url": null}, {"letra": "B", "texto": "Não é feriado", "imagem_url": null}, {"letra": "C", "texto": "Pode ser feriado", "imagem_url": null}, {"letra": "D", "texto": "Feriados não afetam voos", "imagem_url": null}]'::jsonb, 'B', 'Modus tollens'),
('logico', '05d5d2f0-e075-4919-aa85-e0b99e5fe733', 'Silogismos', null, 'Todos os aeroportos internacionais têm alfândega. Guarulhos é internacional. Logo:', null, '[{"letra": "A", "texto": "Guarulhos tem alfândega", "imagem_url": null}, {"letra": "B", "texto": "Guarulhos não tem alfândega", "imagem_url": null}, {"letra": "C", "texto": "Guarulhos é doméstico", "imagem_url": null}, {"letra": "D", "texto": "Alfândega é opcional", "imagem_url": null}]'::jsonb, 'A', 'Silogismo afirmativo válido'),
('logico', '3e101a89-93be-4efa-9216-1c04eef96739', 'Silogismos', null, 'Nenhum animal pode voar na cabine sem transportadora. Rex é um cachorro. Portanto:', null, '[{"letra": "A", "texto": "Rex precisa de transportadora", "imagem_url": null}, {"letra": "B", "texto": "Rex não pode viajar", "imagem_url": null}, {"letra": "C", "texto": "Cachorros são exceção", "imagem_url": null}, {"letra": "D", "texto": "Rex pode ficar solto na cabine", "imagem_url": null}]'::jsonb, 'A', 'Aplicação de regra universal'),
('logico', '7bbcf903-3083-4e71-8486-14c875023e4e', 'Silogismos', null, 'Se há overbooking, passageiros são realocados. Não houve realocação. Logo:', null, '[{"letra": "A", "texto": "Houve overbooking", "imagem_url": null}, {"letra": "B", "texto": "Não houve overbooking", "imagem_url": null}, {"letra": "C", "texto": "Overbooking não gera realocação", "imagem_url": null}, {"letra": "D", "texto": "Passageiros recusaram", "imagem_url": null}]'::jsonb, 'B', 'Modus tollens'),
('logico', '613a8b5e-8687-4f86-b692-efc295bcf957', 'Padrões', null, 'Sequência: A1, B2, C3, D?', null, '[{"letra": "A", "texto": "3", "imagem_url": null}, {"letra": "B", "texto": "4", "imagem_url": null}, {"letra": "C", "texto": "E", "imagem_url": null}, {"letra": "D", "texto": "5", "imagem_url": null}]'::jsonb, 'B', 'Letra avança, número avança. D4'),
('logico', 'd9260d9e-68f0-42d5-8657-867159a0c41f', 'Silogismos', null, 'Todos os voos têm demonstração de segurança. O voo 1234 é um voo. Portanto:', null, '[{"letra": "A", "texto": "Pode não ter demonstração", "imagem_url": null}, {"letra": "B", "texto": "Tem demonstração de segurança", "imagem_url": null}, {"letra": "C", "texto": "Demonstração é opcional", "imagem_url": null}, {"letra": "D", "texto": "Não é um voo", "imagem_url": null}]'::jsonb, 'B', 'Silogismo categórico'),
('logico', '3863e669-86bd-4ed1-94ff-c499c190b69b', 'Silogismos', null, 'Se a turbina falha, o piloto declara emergência. Houve declaração de emergência. Logo:', null, '[{"letra": "A", "texto": "A turbina certamente falhou", "imagem_url": null}, {"letra": "B", "texto": "Não se pode afirmar que a turbina falhou", "imagem_url": null}, {"letra": "C", "texto": "A turbina está funcionando", "imagem_url": null}, {"letra": "D", "texto": "Emergência é falsa", "imagem_url": null}]'::jsonb, 'B', 'Afirmar consequente não prova antecedente'),
('logico', '20d996fa-80cc-41ab-9566-414ca2d72f4a', 'Silogismos', null, 'Nenhum passageiro pode fumar a bordo. Carlos é passageiro. Portanto:', null, '[{"letra": "A", "texto": "Carlos não é passageiro", "imagem_url": null}, {"letra": "B", "texto": "Carlos pode fumar", "imagem_url": null}, {"letra": "C", "texto": "Fumar é permitido em algumas áreas", "imagem_url": null}, {"letra": "D", "texto": "Carlos não pode fumar a bordo", "imagem_url": null}]'::jsonb, 'D', 'Silogismo negativo'),
('logico', 'f54511ce-de2d-40c1-8dc3-3a011a9436c4', 'Silogismos', null, 'Se o passaporte venceu, o embarque é negado. O passaporte de Ana venceu. Logo:', null, '[{"letra": "A", "texto": "Ana embarca normalmente", "imagem_url": null}, {"letra": "B", "texto": "Passaporte vencido é aceito", "imagem_url": null}, {"letra": "C", "texto": "Ana terá embarque negado", "imagem_url": null}, {"letra": "D", "texto": "Depende do destino", "imagem_url": null}]'::jsonb, 'C', 'Modus ponens'),
('logico', '8a1e8658-7154-477a-b45a-cfdafdd066a0', 'Silogismos', null, 'Todos os comissários falam inglês. Quem fala inglês pode atender estrangeiros. Logo:', null, '[{"letra": "A", "texto": "Comissários podem atender estrangeiros", "imagem_url": null}, {"letra": "B", "texto": "Inglês não é necessário", "imagem_url": null}, {"letra": "C", "texto": "Comissários não atendem estrangeiros", "imagem_url": null}, {"letra": "D", "texto": "Estrangeiros não precisam de atendimento", "imagem_url": null}]'::jsonb, 'A', 'Silogismo transitivo válido'),
('logico', 'f06e7d81-64ba-46a8-8b37-99a41fb22e03', 'Silogismos', null, 'Algumas escalas são longas. Escalas longas têm hospedagem. Logo:', null, '[{"letra": "A", "texto": "Todas escalas têm hospedagem", "imagem_url": null}, {"letra": "B", "texto": "Algumas escalas têm hospedagem", "imagem_url": null}, {"letra": "C", "texto": "Nenhuma escala tem hospedagem", "imagem_url": null}, {"letra": "D", "texto": "Hospedagem é rara", "imagem_url": null}]'::jsonb, 'B', 'Conclusão particular'),
('logico', 'dfb368d1-be57-4b25-b95e-406e2762edfb', 'Silogismos', null, 'Se o voo é direto, não há escala. Este voo tem escala. Portanto:', null, '[{"letra": "A", "texto": "O voo é direto", "imagem_url": null}, {"letra": "B", "texto": "Escala não conta", "imagem_url": null}, {"letra": "C", "texto": "Voos diretos podem ter escala", "imagem_url": null}, {"letra": "D", "texto": "O voo não é direto", "imagem_url": null}]'::jsonb, 'D', 'Modus tollens'),
('logico', 'a0cea4d9-12c7-4c6b-8947-b066ca8a680c', 'Analogias', null, 'Piloto está para avião assim como capitão está para:', null, '[{"letra": "A", "texto": "Carro", "imagem_url": null}, {"letra": "B", "texto": "Navio", "imagem_url": null}, {"letra": "C", "texto": "Bicicleta", "imagem_url": null}, {"letra": "D", "texto": "Trem", "imagem_url": null}]'::jsonb, 'B', 'Ambos comandam veículos: piloto/avião, capitão/navio'),
