('logico', '5f311836-a2de-4468-b2cd-c659d27617f5', 'Analogias', null, 'Copiloto está para piloto assim como vice está para:', null, '[{"letra": "A", "texto": "Gerente", "imagem_url": null}, {"letra": "B", "texto": "Diretor", "imagem_url": null}, {"letra": "C", "texto": "Presidente", "imagem_url": null}, {"letra": "D", "texto": "Chefe", "imagem_url": null}]'::jsonb, 'C', 'Segundo em comando'),
('logico', '39e813d7-1af2-4e02-9f5e-aa8f3c6d84e0', 'Analogias', null, 'Radar está para detecção assim como sonar está para:', null, '[{"letra": "A", "texto": "Navegação", "imagem_url": null}, {"letra": "B", "texto": "Som", "imagem_url": null}, {"letra": "C", "texto": "Eco", "imagem_url": null}, {"letra": "D", "texto": "Detecção", "imagem_url": null}]'::jsonb, 'D', 'Mesma função, meios diferentes'),
('logico', 'd5a7f3fb-757a-4475-825f-1b03a08bea8a', 'Analogias', null, 'Cabine de comando está para piloto assim como cozinha está para:', null, '[{"letra": "A", "texto": "Fogo", "imagem_url": null}, {"letra": "B", "texto": "Restaurante", "imagem_url": null}, {"letra": "C", "texto": "Chef", "imagem_url": null}, {"letra": "D", "texto": "Comida", "imagem_url": null}]'::jsonb, 'C', 'Área de trabalho do profissional'),
('logico', 'f4f66af4-ca7e-4f4f-a3ab-9cc73c10ffeb', 'Analogias', null, 'Helicóptero está para rotor assim como avião está para:', null, '[{"letra": "A", "texto": "Motor", "imagem_url": null}, {"letra": "B", "texto": "Asa", "imagem_url": null}, {"letra": "C", "texto": "Cabine", "imagem_url": null}, {"letra": "D", "texto": "Roda", "imagem_url": null}]'::jsonb, 'B', 'Componente de sustentação'),
('logico', '5497df93-b0d0-4bea-8175-9fc47a11e931', 'Analogias', null, 'Janela está para vista assim como corredor está para:', null, '[{"letra": "A", "texto": "Passagem", "imagem_url": null}, {"letra": "B", "texto": "Parede", "imagem_url": null}, {"letra": "C", "texto": "Acesso", "imagem_url": null}, {"letra": "D", "texto": "Banheiro", "imagem_url": null}]'::jsonb, 'C', 'Função principal no avião'),
('logico', '7b9eabd5-ca87-432f-a259-a8ee46083c39', 'Analogias', null, 'Overbooking está para excesso assim como atraso está para:', null, '[{"letra": "A", "texto": "Problema", "imagem_url": null}, {"letra": "B", "texto": "Cancelamento", "imagem_url": null}, {"letra": "C", "texto": "Passageiro", "imagem_url": null}, {"letra": "D", "texto": "Demora", "imagem_url": null}]'::jsonb, 'D', 'Definição do termo'),
('logico', '15f7c1d0-b326-4cfd-bce3-83eaaad68778', 'Analogias', null, 'Classe executiva está para conforto assim como econômica está para:', null, '[{"letra": "A", "texto": "Desconforto", "imagem_url": null}, {"letra": "B", "texto": "Economia", "imagem_url": null}, {"letra": "C", "texto": "Preço", "imagem_url": null}, {"letra": "D", "texto": "Multidão", "imagem_url": null}]'::jsonb, 'B', 'Característica principal'),
('logico', 'dc551994-8b8f-4702-bd6f-0cb68c542e9d', 'raven_matrix', null, 'Analise a matriz e identifique qual figura completa o padrão.', 'https://horsky.com.br/raven-questions/raven-q02.png', '[{"letra": "A", "texto": "A", "imagem_url": null}, {"letra": "B", "texto": "B", "imagem_url": null}, {"letra": "C", "texto": "C", "imagem_url": null}, {"letra": "D", "texto": "D", "imagem_url": null}]'::jsonb, 'D', 'O padrão segue uma lógica de combinação de linhas horizontais e verticais em cada célula da matriz.'),
('logico', 'cca96c12-0363-4e33-ac66-a2b513d39f96', 'raven_matrix', null, 'Analise a matriz e identifique qual figura completa o padrão.', 'https://horsky.com.br/raven-questions/raven-q03.png', '[{"letra": "A", "texto": "A", "imagem_url": null}, {"letra": "B", "texto": "C", "imagem_url": null}, {"letra": "C", "texto": "B", "imagem_url": null}, {"letra": "D", "texto": "D", "imagem_url": null}]'::jsonb, 'D', 'Cada linha e coluna apresenta uma combinação única de formas com linhas internas que se complementam.'),
('logico', '2ad73607-1b9b-43fd-99b6-b09cbc818588', 'raven_matrix', null, 'Analise a matriz e identifique qual figura completa o padrão.', 'https://horsky.com.br/raven-questions/raven-q04.png', '[{"letra": "A", "texto": "B", "imagem_url": null}, {"letra": "B", "texto": "A", "imagem_url": null}, {"letra": "C", "texto": "C", "imagem_url": null}, {"letra": "D", "texto": "D", "imagem_url": null}]'::jsonb, 'D', 'O padrão mostra losangos divididos em seções, onde o preenchimento segue uma regra específica por linha e coluna.'),
('logico', 'aec8d59e-ee8c-480e-8cd8-ce35a0026ee8', 'raven_matrix', null, 'Analise a matriz e identifique qual figura completa o padrão.', 'https://horsky.com.br/raven-questions/raven-q05.png', '[{"letra": "A", "texto": "C", "imagem_url": null}, {"letra": "B", "texto": "B", "imagem_url": null}, {"letra": "C", "texto": "A", "imagem_url": null}, {"letra": "D", "texto": "D", "imagem_url": null}]'::jsonb, 'D', 'Os elementos internos (triângulo, estrela) seguem uma rotação e combinação específica em cada célula.'),
('logico', '63c8e597-bf3e-4b2f-bad1-b047f3639084', 'raven_matrix', null, 'Analise a matriz e identifique qual figura completa o padrão.', 'https://horsky.com.br/raven-questions/raven-q06.png', '[{"letra": "A", "texto": "A", "imagem_url": null}, {"letra": "B", "texto": "D", "imagem_url": null}, {"letra": "C", "texto": "B", "imagem_url": null}, {"letra": "D", "texto": "C", "imagem_url": null}]'::jsonb, 'B', 'A sequência numérica 5, 7, 9, 11 segue uma progressão aritmética com razão 2.'),
('logico', '792975fa-c3fd-4244-9774-f7d92b245f88', 'raven_matrix', null, 'Analise a matriz e identifique qual figura completa o padrão.', 'https://horsky.com.br/raven-questions/raven-q07.png', '[{"letra": "A", "texto": "B", "imagem_url": null}, {"letra": "B", "texto": "D", "imagem_url": null}, {"letra": "C", "texto": "C", "imagem_url": null}, {"letra": "D", "texto": "A", "imagem_url": null}]'::jsonb, 'B', 'Formas aninhadas seguem uma lógica de rotação e transformação progressiva.'),
('logico', 'd43d642c-7019-4bb6-b66c-c49e733dba89', 'raven_matrix', null, 'Analise a matriz e identifique qual figura completa o padrão.', 'https://horsky.com.br/raven-questions/raven-q08.png', '[{"letra": "A", "texto": "A", "imagem_url": null}, {"letra": "B", "texto": "D", "imagem_url": null}, {"letra": "C", "texto": "B", "imagem_url": null}, {"letra": "D", "texto": "C", "imagem_url": null}]'::jsonb, 'D', 'Os chevrons e pontos seguem uma combinação específica onde cada linha/coluna tem uma configuração única.'),
('logico', 'fd81b91b-99c5-4028-9534-5a990af05b33', 'raven_matrix', null, 'Analise a matriz e identifique qual figura completa o padrão.', 'https://horsky.com.br/raven-questions/raven-q09.png', '[{"letra": "A", "texto": "D", "imagem_url": null}, {"letra": "B", "texto": "C", "imagem_url": null}, {"letra": "C", "texto": "A", "imagem_url": null}, {"letra": "D", "texto": "B", "imagem_url": null}]'::jsonb, 'A', 'As linhas conectoras entre as formas seguem um padrão de posicionamento lógico.'),
('logico', 'b900624a-8507-4be3-84b1-9f414b93fed5', 'raven_matrix', null, 'Analise a matriz e identifique qual figura completa o padrão.', 'https://horsky.com.br/raven-questions/raven-q10.png', '[{"letra": "A", "texto": "B", "imagem_url": null}, {"letra": "B", "texto": "D", "imagem_url": null}, {"letra": "C", "texto": "C", "imagem_url": null}, {"letra": "D", "texto": "A", "imagem_url": null}]'::jsonb, 'A', 'A sobreposição de formas segue uma regra de XOR visual onde elementos se combinam ou cancelam.'),
('logico', '2555b9a0-5e62-4db3-9451-dfe6272412e4', 'raven_matrix', null, 'Analise o padrão de orientação das linhas em cada célula da matriz e identifique qual figura completa a sequência.', 'https://horsky.com.br/raven-questions/raven-q11.png', '[{"letra": "A", "texto": "A", "imagem_url": null}, {"letra": "B", "texto": "B", "imagem_url": null}, {"letra": "C", "texto": "C", "imagem_url": null}, {"letra": "D", "texto": "D", "imagem_url": null}]'::jsonb, 'C', 'O padrão mostra linhas em diferentes orientações (diagonais, horizontais, verticais). Cada linha da matriz segue uma progressão específica de orientação, e a opção C completa corretamente o padrão com linhas diagonais para baixo-direita.'),
('logico', 'fb68606c-4189-439c-aac1-ecbc4347d80a', 'raven_matrix', null, 'Observe o número de linhas horizontais e pontos em cada célula. Qual figura completa o padrão?', 'https://horsky.com.br/raven-questions/raven-q12.png', '[{"letra": "A", "texto": "C", "imagem_url": null}, {"letra": "B", "texto": "A", "imagem_url": null}, {"letra": "C", "texto": "D", "imagem_url": null}, {"letra": "D", "texto": "B", "imagem_url": null}]'::jsonb, 'C', 'O padrão mostra um aumento progressivo no número de linhas horizontais (1→2→3) e pontos. A última célula deve ter 3 linhas e 3 pontos distribuídos, correspondendo à opção D.'),
('logico', '37d1ceea-0fae-425b-beb8-e0a73541b114', 'raven_matrix', null, 'Identifique o padrão de rotação das formas em L e selecione a figura que completa a matriz.', 'https://horsky.com.br/raven-questions/raven-q13.png', '[{"letra": "A", "texto": "D", "imagem_url": null}, {"letra": "B", "texto": "A", "imagem_url": null}, {"letra": "C", "texto": "C", "imagem_url": null}, {"letra": "D", "texto": "B", "imagem_url": null}]'::jsonb, 'B', 'As formas em L seguem um padrão de rotação de 90 graus em cada célula. Analisando a progressão em cada linha, a opção A apresenta a forma na posição correta para completar o padrão.'),
('logico', '1915110e-e40d-44cd-8210-d194c30402ab', 'raven_matrix', null, 'Analise o padrão de preenchimento dos triângulos dentro dos quadrados divididos e selecione a resposta correta.', 'https://horsky.com.br/raven-questions/raven-q14.png', '[{"letra": "A", "texto": "C", "imagem_url": null}, {"letra": "B", "texto": "D", "imagem_url": null}, {"letra": "C", "texto": "A", "imagem_url": null}, {"letra": "D", "texto": "B", "imagem_url": null}]'::jsonb, 'D', 'O padrão envolve triângulos preenchidos em diferentes posições dentro de quadrados divididos. Combinando os padrões de cada linha e coluna, a opção B com triângulos laterais preenchidos completa corretamente a matriz.'),
('logico', '4be0a4f4-3624-45c8-85ba-9a42499bf750', 'raven_matrix', null, 'Descubra a relação matemática entre o número de lados das formas e os valores numéricos apresentados.', 'https://horsky.com.br/raven-questions/raven-q15.png', '[{"letra": "A", "texto": "B", "imagem_url": null}, {"letra": "B", "texto": "D", "imagem_url": null}, {"letra": "C", "texto": "A", "imagem_url": null}, {"letra": "D", "texto": "C", "imagem_url": null}]'::jsonb, 'A', 'A regra é: número de lados × 3. Triângulo (3 lados) = 9, Losango (4 lados) = 12, Pentágono (5 lados) = 15. A resposta correta é B (15).'),
('logico', 'c1caf451-a0c6-4e94-8531-cda34b50a436', 'raven_matrix', null, 'Observe a relação entre os círculos grandes e a área central. Qual figura representa corretamente a interseção?', 'https://horsky.com.br/raven-questions/raven-q16.png', '[{"letra": "A", "texto": "B", "imagem_url": null}, {"letra": "B", "texto": "D", "imagem_url": null}, {"letra": "C", "texto": "C", "imagem_url": null}, {"letra": "D", "texto": "A", "imagem_url": null}]'::jsonb, 'D', 'O quadrado central mostra a área de interseção dos círculos sobrepostos. Analisando a sobreposição dos 3 círculos, a opção A representa corretamente a interseção resultante.'),
('logico', '474bfd51-f500-4f19-8f82-88320af2fcde', 'raven_matrix', null, 'Encontre o padrão numérico na matriz 3x3 e determine qual número completa a sequência.', 'https://horsky.com.br/raven-questions/raven-q17.png', '[{"letra": "A", "texto": "D", "imagem_url": null}, {"letra": "B", "texto": "C", "imagem_url": null}, {"letra": "C", "texto": "A", "imagem_url": null}, {"letra": "D", "texto": "B", "imagem_url": null}]'::jsonb, 'A', 'Na matriz numérica (72, 60, 66 | 48, 36, 42 | 83, 71, ?), observa-se que a diferença entre 83 e 71 é 12, e seguindo o padrão alternado de +6/-6, o valor correto é 71 + 6 = 77 (opção D).'),
('logico', '9d3c4bfa-fe4a-4795-a579-143158ece60d', 'raven_matrix', null, 'Analise como as formas se combinam em cada linha para gerar o resultado. Qual figura completa o padrão?', 'https://horsky.com.br/raven-questions/raven-q18.png', '[{"letra": "A", "texto": "D", "imagem_url": null}, {"letra": "B", "texto": "B", "imagem_url": null}, {"letra": "C", "texto": "A", "imagem_url": null}, {"letra": "D", "texto": "C", "imagem_url": null}]'::jsonb, 'B', 'O padrão mostra combinação de formas: losango + pontos = losango com pontos, cruz + X = asterisco. Na terceira linha, losango com linhas + X com pontos deve resultar em asterisco com pontos e losango (opção B).'),
('logico', '48be8d7e-8610-45f8-8885-506aad8e5083', 'raven_matrix', null, 'Identifique a relação matemática entre os números nas colunas e encontre o valor que falta.', 'https://horsky.com.br/raven-questions/raven-q19.png', '[{"letra": "A", "texto": "A", "imagem_url": null}, {"letra": "B", "texto": "B", "imagem_url": null}, {"letra": "C", "texto": "D", "imagem_url": null}, {"letra": "D", "texto": "C", "imagem_url": null}]'::jsonb, 'D', 'O padrão é: terceira coluna = segunda coluna ÷ 2. Verificando: 50÷2=25 ✓, 32÷2=16 ✓. Portanto, 40÷2=20 (opção C).'),
('logico', '01c2b212-5edc-4fb3-b293-db26abf1e3c2', 'raven_matrix', null, 'Observe os três estilos de preenchimento (tracejado, contorno, preenchido) distribuídos entre as formas. Qual figura completa a matriz?', 'https://horsky.com.br/raven-questions/raven-q20.png', '[{"letra": "A", "texto": "A", "imagem_url": null}, {"letra": "B", "texto": "B", "imagem_url": null}, {"letra": "C", "texto": "D", "imagem_url": null}, {"letra": "D", "texto": "C", "imagem_url": null}]'::jsonb, 'C', 'Cada linha apresenta os três estilos (tracejado, contorno sólido, preenchido) distribuídos entre quadrado, círculo e triângulo. Na terceira linha: quadrado contorno, círculo preenchido, então o triângulo deve ser tracejado (opção D).'),
('logico', '9cf843d3-db86-488e-8055-7932bbe11279', 'raven_matrix', null, 'Analise a matriz e identifique qual figura completa o padrão.', 'https://horsky.com.br/raven-questions/raven-q01.png', '[{"letra": "A", "texto": "A", "imagem_url": null}, {"letra": "B", "texto": "D", "imagem_url": null}, {"letra": "C", "texto": "C", "imagem_url": null}, {"letra": "D", "texto": "B", "imagem_url": null}]'::jsonb, 'B', 'O padrão mostra uma progressão de formas geométricas onde cada célula combina elementos específicos seguindo uma lógica de adição/subtração.')
insert into questoes (banco, origem_id, categoria, contexto, enunciado, imagem_url, alternativas, correta, explicacao) values
('numerico', '7501908e-f621-4aa2-833d-0197b6842225', 'Raciocínio numérico', null, 'Um voo de São Paulo a Miami dura 9h20min. Se a decolagem for às 23h40, considerando fuso horário de -2h em Miami, que horas serão no destino ao pousar?', null, '[{"letra": "A", "texto": "11h00", "imagem_url": null}, {"letra": "B", "texto": "09h00", "imagem_url": null}, {"letra": "C", "texto": "13h00", "imagem_url": null}, {"letra": "D", "texto": "07h00", "imagem_url": null}]'::jsonb, 'D', null),
('numerico', '706d0ad2-1901-464c-b565-a75706209062', 'Raciocínio numérico', null, 'Uma aeronave consome 3.200 litros de combustível por hora. Para um voo de 4h45min, quantos litros serão necessários (considerando reserva de 20%)?', null, '[{"letra": "A", "texto": "21.000 litros", "imagem_url": null}, {"letra": "B", "texto": "15.200 litros", "imagem_url": null}, {"letra": "C", "texto": "18.240 litros", "imagem_url": null}, {"letra": "D", "texto": "19.200 litros", "imagem_url": null}]'::jsonb, 'C', null),
('numerico', '7287bc70-d802-44cf-920e-19ed5578a451', 'Raciocínio numérico', null, 'Em um voo com 280 passageiros, 35% escolheram refeição vegetariana e 15% infantil. Quantas refeições padrão foram servidas?', null, '[{"letra": "A", "texto": "98 refeições", "imagem_url": null}, {"letra": "B", "texto": "112 refeições", "imagem_url": null}, {"letra": "C", "texto": "126 refeições", "imagem_url": null}, {"letra": "D", "texto": "140 refeições", "imagem_url": null}]'::jsonb, 'D', null),
('numerico', 'ce9d118d-be8c-4a13-a441-8c3e236aa811', 'Raciocínio numérico', null, 'Um comissário trabalha 85 horas por mês e recebe R$ 4.250,00. Qual seu valor por hora trabalhada?', null, '[{"letra": "A", "texto": "R$ 45,00", "imagem_url": null}, {"letra": "B", "texto": "R$ 50,00", "imagem_url": null}, {"letra": "C", "texto": "R$ 55,00", "imagem_url": null}, {"letra": "D", "texto": "R$ 60,00", "imagem_url": null}]'::jsonb, 'B', null),
