('sjt', '3ad7ce11-8403-49f1-8d59-c38f633a4dac', 'Julgamento situacional', null, 'Um passageiro está tendo uma crise de ansiedade severa.', null, '[{"letra": "A", "texto": "Ignoro e espero que passe", "imagem_url": null}, {"letra": "B", "texto": "Chamo atenção de outros passageiros para a situação", "imagem_url": null}, {"letra": "C", "texto": "Aproximo-me com calma, uso técnicas de respiração, mantenho comunicação tranquila e avalio necessidade de ajuda médica", "imagem_url": null}, {"letra": "D", "texto": "Digo para se acalmar e que não há motivo para preocupação", "imagem_url": null}]'::jsonb, 'C', null),
('sjt', '9efa94d1-8e34-4d79-a9c9-ca4393de7dac', 'Julgamento situacional', null, 'Você percebe que há um desequilíbrio na distribuição de tarefas entre a tripulação.', null, '[{"letra": "A", "texto": "Reclamo em voz alta sobre a injustiça", "imagem_url": null}, {"letra": "B", "texto": "Reduzo meu próprio desempenho para equilibrar", "imagem_url": null}, {"letra": "C", "texto": "Proponho redistribuição de forma construtiva ao chefe de cabine", "imagem_url": null}, {"letra": "D", "texto": "Aceito silenciosamente mesmo sobrecarregado", "imagem_url": null}]'::jsonb, 'C', null),
('sjt', '5110f1e4-7821-4a8e-a073-a3bf4de75a83', 'Julgamento situacional', null, 'Um passageiro está tentando acessar a área de serviço (galley) sem permissão.', null, '[{"letra": "A", "texto": "Permito por educação", "imagem_url": null}, {"letra": "B", "texto": "Empurro-o para fora", "imagem_url": null}, {"letra": "C", "texto": "Explico gentilmente que a área é restrita e ofereço ajuda com o que ele precisar", "imagem_url": null}, {"letra": "D", "texto": "Ignoro e continuo trabalhando", "imagem_url": null}]'::jsonb, 'C', null),
('sjt', '9e6853e6-2932-44cc-ad74-aaad6de5b54d', 'Julgamento situacional', null, 'Você cometeu um erro no serviço e um passageiro percebeu.', null, '[{"letra": "A", "texto": "Assumo o erro, peço desculpas sinceras e corrijo imediatamente", "imagem_url": null}, {"letra": "B", "texto": "Culpo outro colega", "imagem_url": null}, {"letra": "C", "texto": "Minimizo a importância do erro", "imagem_url": null}, {"letra": "D", "texto": "Nego ter cometido erro", "imagem_url": null}]'::jsonb, 'A', null),
('sjt', 'b24dee84-a133-47f4-8f1d-37279b1f155b', 'Julgamento situacional', null, 'Um passageiro está tentando usar os toiletes durante a decolagem.', null, '[{"letra": "A", "texto": "Grito instruções de longe", "imagem_url": null}, {"letra": "B", "texto": "Explico firmemente a regulamentação de segurança e acompanho de volta ao assento", "imagem_url": null}, {"letra": "C", "texto": "Ignoro e espero que volte sozinho", "imagem_url": null}, {"letra": "D", "texto": "Deixo ir para evitar discussão", "imagem_url": null}]'::jsonb, 'B', null),
('sjt', '6b6cdab2-33f1-42b6-83e8-0b82aef9c9f9', 'Julgamento situacional', null, 'Você ouve um colega dando informação incorreta a um passageiro sobre conexões.', null, '[{"letra": "A", "texto": "Informo ao passageiro que o colega estava errado", "imagem_url": null}, {"letra": "B", "texto": "Intervenho educadamente corrigindo a informação de forma a não constranger o colega", "imagem_url": null}, {"letra": "C", "texto": "Corrijo o colega publicamente", "imagem_url": null}, {"letra": "D", "texto": "Deixo o passageiro descobrir sozinho depois", "imagem_url": null}]'::jsonb, 'B', null),
('sjt', 'b1a79d95-c76f-4dac-80fc-6d77fdcc5a19', 'Julgamento situacional', null, 'Um passageiro está claramente embriagado mas não está causando problemas (ainda).', null, '[{"letra": "A", "texto": "Monitoro discretamente, evito servir mais álcool e informo a equipe", "imagem_url": null}, {"letra": "B", "texto": "Sirvo mais bebidas normalmente", "imagem_url": null}, {"letra": "C", "texto": "Confronto sobre sua embriaguez", "imagem_url": null}, {"letra": "D", "texto": "Ignoro completamente", "imagem_url": null}]'::jsonb, 'A', null),
('sjt', 'cadf4427-f9ca-4024-917d-e27a62267698', 'Julgamento situacional', null, 'O sistema de aviso de apertar cintos falha e você precisa comunicar aos passageiros.', null, '[{"letra": "A", "texto": "Espero o sistema ser restaurado", "imagem_url": null}, {"letra": "B", "texto": "Assumo que todos sabem que devem apertar", "imagem_url": null}, {"letra": "C", "texto": "Comunico apenas aos passageiros próximos", "imagem_url": null}, {"letra": "D", "texto": "Faço anúncio verbal claro e verifico visualmente se passageiros atenderam", "imagem_url": null}]'::jsonb, 'D', null),
('sjt', '3df02f40-9dd0-4643-b066-5088caa20165', 'Julgamento situacional', null, 'Um passageiro reclama que foi maltratado por outro membro da tripulação.', null, '[{"letra": "A", "texto": "Defendo meu colega automaticamente", "imagem_url": null}, {"letra": "B", "texto": "Digo que não posso fazer nada sobre isso", "imagem_url": null}, {"letra": "C", "texto": "Critico meu colega na frente do passageiro", "imagem_url": null}, {"letra": "D", "texto": "Escuto atentamente, peço desculpas pela experiência negativa e encaminho ao chefe de cabine", "imagem_url": null}]'::jsonb, 'D', null),
('sjt', '1a680d2e-bac1-4047-83ba-909ed5e6c54e', 'Julgamento situacional', null, 'Você está atrasado para o check-in do próximo voo devido a atraso do voo anterior.', null, '[{"letra": "A", "texto": "Corro e não informo ninguém sobre meu estado", "imagem_url": null}, {"letra": "B", "texto": "Informo a situação à supervisão e me apresento assim que possível mantendo compostura", "imagem_url": null}, {"letra": "C", "texto": "Reclamo publicamente sobre a escala mal planejada", "imagem_url": null}, {"letra": "D", "texto": "Deixo de fazer o próximo voo sem avisar", "imagem_url": null}]'::jsonb, 'B', null),
('sjt', '9658b8ca-49dd-4136-8abc-eb8c0d0029c5', 'Julgamento situacional', null, 'Um passageiro está tentando usar equipamento não autorizado (drone/transmissor).', null, '[{"letra": "A", "texto": "Informo sobre a proibição, solicito que guarde e reporto ao comandante se necessário", "imagem_url": null}, {"letra": "B", "texto": "Deixo para a segurança do aeroporto lidar depois", "imagem_url": null}, {"letra": "C", "texto": "Confisco o equipamento sem explicação", "imagem_url": null}, {"letra": "D", "texto": "Ignoro pois não sei as regras exatas", "imagem_url": null}]'::jsonb, 'A', null),
('sjt', '73fdfb32-0267-4bd6-b144-aae62a43e30e', 'Julgamento situacional', null, 'Você recebe crítica de um passageiro nas redes sociais após o voo que considera injusta.', null, '[{"letra": "A", "texto": "Reclamo com colegas sobre a injustiça", "imagem_url": null}, {"letra": "B", "texto": "Respondo publicamente defendendo-me agressivamente", "imagem_url": null}, {"letra": "C", "texto": "Mantenho profissionalismo, não respondo pessoalmente e encaminho para canais oficiais se necessário", "imagem_url": null}, {"letra": "D", "texto": "Identifico o passageiro e confronto", "imagem_url": null}]'::jsonb, 'C', null),
('sjt', '8241f6f1-d59a-42a0-a296-d16ad50733b7', 'Julgamento situacional', null, 'Um passageiro está transportando animal de suporte emocional que outros passageiros temem.', null, '[{"letra": "A", "texto": "Mudo o animal de lugar sem consultar o dono", "imagem_url": null}, {"letra": "B", "texto": "Busco solução que acomode ambas as necessidades, comunicando-se com todos os envolvidos", "imagem_url": null}, {"letra": "C", "texto": "Digo aos passageiros que tem medo para lidarem com isso", "imagem_url": null}, {"letra": "D", "texto": "Exijo que o animal seja guardado", "imagem_url": null}]'::jsonb, 'B', null),
('sjt', 'e752be76-4de6-4a80-9a2e-4be56f67acc5', 'Julgamento situacional', null, 'Você está em descanso programado mas é chamado para ajudar devido a situação na cabine.', null, '[{"letra": "A", "texto": "Ignoro o chamado", "imagem_url": null}, {"letra": "B", "texto": "Ajudo prontamente avaliando a necessidade e retomo descanso quando possível", "imagem_url": null}, {"letra": "C", "texto": "Recuso pois é meu direito descansar", "imagem_url": null}, {"letra": "D", "texto": "Ajudo mas reclamo constantemente", "imagem_url": null}]'::jsonb, 'B', null),
('sjt', '253cad07-a268-4176-9695-f2726bb16035', 'Julgamento situacional', null, 'Um passageiro alega ter alergia alimentar severa que não foi registrada na reserva.', null, '[{"letra": "A", "texto": "Digo que não há nada que possamos fazer", "imagem_url": null}, {"letra": "B", "texto": "Peço que coma o que trouxe de casa", "imagem_url": null}, {"letra": "C", "texto": "Verifico todos os ingredientes disponíveis, busco alternativas seguras e informo o comandante", "imagem_url": null}, {"letra": "D", "texto": "Ofereço qualquer comida dizendo que não deve ter alérgeno", "imagem_url": null}]'::jsonb, 'C', null),
('sjt', '270c36f9-42a7-4fa7-b2c9-839ed31d08ac', 'Julgamento situacional', null, 'Você percebe que a porta do galley não está fechando corretamente.', null, '[{"letra": "A", "texto": "Reporto imediatamente à tripulação técnica e busco solução temporária segura", "imagem_url": null}, {"letra": "B", "texto": "Espero alguém mais notar", "imagem_url": null}, {"letra": "C", "texto": "Tento consertar sozinho sem avisar", "imagem_url": null}, {"letra": "D", "texto": "Ignoro pois não parece grave", "imagem_url": null}]'::jsonb, 'A', null),
('sjt', 'f4e6d9ab-d74a-41d0-a8f1-4e93b52c5f0f', 'Julgamento situacional', null, 'Um passageiro está usando linguagem de assédio sexual com uma colega.', null, '[{"letra": "A", "texto": "Peço que outro passageiro intervenha", "imagem_url": null}, {"letra": "B", "texto": "Intervenho firmemente, apoio minha colega e escalo a situação conforme procedimentos", "imagem_url": null}, {"letra": "C", "texto": "Ignoro para não criar conflito", "imagem_url": null}, {"letra": "D", "texto": "Sugiro que minha colega ignore", "imagem_url": null}]'::jsonb, 'B', null),
('sjt', 'b660637f-5666-42eb-87a1-00c24b32ca6a', 'Julgamento situacional', null, 'O voo está com ocupação muito baixa e passageiros querem mudar para assentos melhores.', null, '[{"letra": "A", "texto": "Nego todas as mudanças rigidamente", "imagem_url": null}, {"letra": "B", "texto": "Permito mudanças razoáveis que não afetem balanceamento ou segurança, verificando com a tripulação", "imagem_url": null}, {"letra": "C", "texto": "Permito qualquer mudança sem verificar", "imagem_url": null}, {"letra": "D", "texto": "Cobro informalmente pela mudança", "imagem_url": null}]'::jsonb, 'B', null),
