('sjt', '8fc7890f-4e50-4525-ba63-56f52ef39fa0', 'Julgamento situacional', null, 'Você percebe um odor estranho que pode indicar vazamento de fluido na aeronave.', null, '[{"letra": "A", "texto": "Pergunto aos passageiros se sentem o cheiro", "imagem_url": null}, {"letra": "B", "texto": "Espero para ver se continua", "imagem_url": null}, {"letra": "C", "texto": "Reporto imediatamente ao comandante e monitoro a situação", "imagem_url": null}, {"letra": "D", "texto": "Ignoro pois pode ser imaginação", "imagem_url": null}]'::jsonb, 'C', null),
('sjt', '2f1ebdec-d622-4e5b-80b1-380644952ea0', 'Julgamento situacional', null, 'Um passageiro está tentando fazer proselitismo religioso com outros passageiros que parecem desconfortáveis.', null, '[{"letra": "A", "texto": "Mudo os outros passageiros de lugar", "imagem_url": null}, {"letra": "B", "texto": "Aproximo-me sugerindo que respeite o espaço dos demais passageiros durante o voo", "imagem_url": null}, {"letra": "C", "texto": "Ignoro pois é liberdade de expressão", "imagem_url": null}, {"letra": "D", "texto": "Discuto sobre religião com ele", "imagem_url": null}]'::jsonb, 'B', null),
